\vcenter{
\xymatrix{
A_2^\bullet \ar[d]^0 \ar[r] &
B_2^\bullet \ar[r] \ar[d]^{b'} &
C_2^\bullet \ar[d]^0 \\
A_3^\bullet \ar[r] & B_3^\bullet \ar[r] & C_3^\bullet
}
}
$$
commute in $K(\mathcal{A})$. Then $b' \circ b = 0$ in $K(\mathcal{A})$.

